        score -= 1.0;
    }

    // Penalty for leaving a large fraction of space unused
    if residual_ratio > 0.8 {
        score += (residual_ratio - 0.8).powf(2.0) * 5.0;
    }

    // Next‑item mismatch penalty / reward
    if next_item_size > 0 && post_residual > 0 {
        let diff = next_item_size as i32 - post_residual as i32;
        if diff > 0 {
            // next item too big for the remaining gap
            score += (diff as f64).powf(1.2) * 1.8;
        } else {
            // next item fits better
            score -= (diff.abs() as f64).powf(0.9) * 0.6;
        }
    }

    // Open‑bin pressure: stronger early in the stream
    score += (open_bins_count as f64).powf(1.0) * 0.3 * (1.0 - progress).powf(1.1);

    // Fitting‑bins pressure: many options means higher cost for a poor fit
