    score += dev * dev * 0.015;

    // Pre‑residual deviation (how far the current bin is from the mean)
    let pre_dev = (mean_residual - bin_residual as f64).abs();
    score += pre_dev * 0.03;

    // New‑bin candidate penalty
    if bin_residual == bin_capacity {
        let new_bin_penalty = 3.0 + (fitting_bins_count as f64) * 0.3;
        score += new_bin_penalty;
    }

    // Lookahead: penalise if next item is significantly larger than the gap
    if next_item_size > 2 * post_residual {
        score += 2.5;
    }

    // Residual far above mean
