pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // ------------------------------------------------------------------
    // Base score – log‑scaled to damp very large gaps while keeping small
    // gaps penalised sharply.
    // ------------------------------------------------------------------
    let mut score = ((post_residual as f64) + 1.0).ln();

    // ------------------------------------------------------------------
    // Residual ratio penalty – combine linear, quadratic, and cubic terms
    // to heavily penalise bins that leave a large fraction of capacity unused.
    // ------------------------------------------------------------------
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    score += residual_ratio * 10.0
        + residual_ratio.powi(2) * 25.0
        + residual_ratio.powi(3) * 8.0;

    // ------------------------------------------------------------------
    // Tight gap penalty – extremely bad if the residual is below a
    // small threshold (i.e. the bin is almost full).
    // ------------------------------------------------------------------
    if post_residual < 3 {
        score += 25.0;
    }

    // ------------------------------------------------------------------
    // Look‑ahead penalty – if the next item cannot fit in the residual,
    // we strongly discourage leaving a gap that will be wasted.
    // ------------------------------------------------------------------
    if next_item_size > 0 && post_residual > 0 {
        let need = next_item_size as i32 - post_residual as i32;
        if need > 0 {
            // Use a sub‑linear exponent to avoid over‑penalising large gaps
            score += (need as f64).powf(1.2) * 2.0;
        }
    }

    // ------------------------------------------------------------------
    // Single‑fitting‑bin penalty – avoid leaving a non‑zero residual when
    // no other bin could accept the item.
    // ------------------------------------------------------------------
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 10.0;
    }

    // ------------------------------------------------------------------
    // Open‑bin pressure – logarithmic growth to keep the number of open
    // bins under control as the stream progresses.
    // ------------------------------------------------------------------
    score += (open_bins_count as f64).ln() * 0.5;

    // ------------------------------------------------------------------
    // Progress penalty – tighten residual tolerance as we approach the end
    // of the stream.
    // ------------------------------------------------------------------
    let progress = step_index as f64 / total_items as f64;
    score += progress.powi(2) * post_residual as f64 * 0.15;

    // ------------------------------------------------------------------
    // Deviation from mean residual – slight penalty for deviating from
    // the average residual, but we reward closeness before placement.
    // ------------------------------------------------------------------
    let dev = (mean_residual - post_residual as f64).abs();
    score += dev * 0.05;

    let pre_dev = (mean_residual - bin_residual as f64).abs();
    score -= pre_dev * 0.03; // reward closeness before packing

    // ------------------------------------------------------------------
    // New‑bin discouragement – penalise opening a brand‑new bin when
    // several other bins could accept the item.
    // ------------------------------------------------------------------
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 6.0;
    }

    // ------------------------------------------------------------------
    // Look‑ahead relative to post residual – if the next item is larger
    // than 1.5× the residual, we prefer a bin that leaves more space.
    // ------------------------------------------------------------------
    if next_item_size > 0 && next_item_size > (post_residual as u32 * 3 / 2) {
        score += 4.0;
    }

    // ------------------------------------------------------------------
    // Extra look‑ahead – if the next item is more than half the bin
    // capacity and the bin is almost empty, penalise opening it now.
    // ------------------------------------------------------------------
    if next_item_size > bin_capacity / 2 && post_residual < bin_capacity / 4 {
        score += 6.0;
    }

    // ------------------------------------------------------------------
    // Open‑limit penalty – keep the number of open bins below a dynamic
    // threshold proportional to the stream length.
    // ------------------------------------------------------------------
    let open_limit = (total_items / 15).max(1);
    if open_bins_count > open_limit {
        score += 0.3 * ((open_bins_count as f64 - open_limit as f64).ln());
    }

    // ------------------------------------------------------------------
    // Ratio‑based deviation from mean residual ratio – penalise bins
    // whose residual ratio deviates from the average ratio.
    // ------------------------------------------------------------------
    let mean_ratio = mean_residual / bin_capacity as f64;
    let ratio_dev = (residual_ratio - mean_ratio).abs();
    score += ratio_dev * 7.0;

    // ------------------------------------------------------------------
    // Optional synergy reward – if the bin has more residual before
    // packing than after, and the residual ratio is small, reward it.
    // ------------------------------------------------------------------
    if bin_residual > post_residual && residual_ratio < 0.3 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
