    let dev = (mean_residual - post_residual_f).abs();
    score += dev * 0.05;

    // Prefer bins whose current residual is close to mean before placing
    let pre_dev = (mean_residual - bin_residual as f64).abs();
    score += pre_dev * 0.03;

    // New‑bin discouragement when many bins can fit
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 7.0;
    }

    // Lookahead: if next item is large relative to current gap, favour a larger residual
    if next_item_size > 2 * post_residual {
        score += 4.0;
    }

    // Extra lookahead: next item > half capacity but current bin is almost empty
    if next_item_size > bin_capacity / 2 && post_residual < bin_capacity / 4 {
        score += 6.0;
    }

    // Penalise excess open bins when the stream is long
    let open_limit = (total_items / 25).max(1);
    if open_bins_count > open_limit {
        score += 0.15 * ((open_bins_count as f64 - open_limit as f64).sqrt());
    }

    // Ratio‑based deviation from mean residual ratio
    let mean_ratio = mean_residual / bin_cap_f;
    let ratio_dev = (residual_ratio - mean_ratio).abs();
    score += ratio_dev * 7.0;

    // Reward when the item size matches the residual after placement
    let residual_closeness = (post_residual_f - item_size as f64).abs();
    score -= residual_closeness * 0.02;

    // Couple with open bins: penalise large residuals in many‑open‑bin contexts
    if open_bins_count > 10 && post_residual_f > bin_cap_f * 0.6 {
        score += 5.0;
    }

    score
}

